/// <summary>
/// The <c>METDallasPicklistRegCompleteContract</c> class is a contract class used for the MET Dallas picklist registration completion process.
/// </summary>
[DataContract]
class METDallasPicklistRegCompleteContract
{
    int tasksNumber;
    container wmsOrderTransRouteSet;
    container routeIdCon;

}

Method.Source:
/// <summary>
/// This method takes task numbers.
/// </summary>
/// <param name = "_tasksNumber">TaskNumber</param>
/// <returns>TaskNumber</returns>
[DataMember, SysOperationLabel("@MET:NumOfParallelTasks")]
public int parmParallelTasksNumber(int _tasksNumber = tasksNumber)
{
    tasksNumber = _tasksNumber;
    return tasksNumber;
}

/// <summary>
/// Gets or sets the WMS order transaction route set.
/// </summary>
/// <param name = "wmsOrderTransRoute"> WMS order transaction route set.</param>
/// <returns> WMS order transaction route set.</returns>
[DataMember, SysOperationLabel("@MET:PicklistRouteSet")]
public container parmWMSOrderTransRouteSet(container _wmsOrderTransRouteSet = wmsOrderTransRouteSet)
{
    wmsOrderTransRouteSet = _wmsOrderTransRouteSet;
    return wmsOrderTransRouteSet;
}

/// <summary>
/// Gets or sets picking routes container.
/// </summary>
/// <param name = "_routeIdCon"> Picking routes container.</param>
/// <returns> Picking routes container.</returns>
[DataMember, SysOperationLabel("@MET:PickingRoutes")]
public container parmRouteIdCon(container _routeIdCon = routeIdCon)
{
    routeIdCon = _routeIdCon;
    return routeIdCon;
}
